// ⚙️  Edit these values before running
return [{
  json: {
    case_id: '',
  }
}];

const raw = $input.first().json;
const caseData = raw.data ?? raw;

const summary =
  caseData.case?.description ??
  caseData.case?.case_description ??
  caseData.case_description ??
  caseData.summary ??
  null;

if (!summary) {
  return [{
    json: {
      ...raw,
      _summary_found:  false,
      _summary_text:   null,
      _prompt_count:   0,
      _parsed_prompts: []
    }
  }];
}

const hasPrompts = summary.includes('{{AI_PROMPT:');

return [{
  json: {
    ...raw,
    _summary_found:  true,
    _summary_text:   summary,
    _prompt_count:   hasPrompts ? (summary.match(/\{\{AI_PROMPT:/g) ?? []).length : 0,
    _parsed_prompts: []
  }
}];

const item    = $input.first().json;
const summary = item._summary_text;

if (!summary) {
  return [{ json: { ...item, _parsed_prompts: [] } }];
}

const lines         = summary.split('\n');
const headingRe     = /^#{1,6}\s+.+/;
const promptStartRe = /\{\{AI_PROMPT:/;

const parsedPrompts = [];
let currentHeading  = '(preamble)';
let i = 0;

while (i < lines.length) {
  const line = lines[i];

  if (headingRe.test(line.trim())) {
    currentHeading = line.trim();
    i++;
    continue;
  }

  if (promptStartRe.test(line)) {
    const blockLines = [line];
    let j = i + 1;
    while (j < lines.length && !blockLines.join('').includes('}}')) {
      blockLines.push(lines[j]);
      j++;
    }
    const fullBlock  = blockLines.join('\n');
    const innerMatch = fullBlock.match(/\{\{AI_PROMPT:\s*([\s\S]*?)\}\}/);
    if (innerMatch) {
      parsedPrompts.push({
        index:       parsedPrompts.length,
        heading:     currentHeading,
        prompt:      innerMatch[1].trim(),
        placeholder: fullBlock
      });
    }
    i = j;
    continue;
  }
  i++;
}

return [{
  json: {
    ...item,
    _summary_found:  item._summary_found,
    _summary_text:   summary,
    _prompt_count:   parsedPrompts.length,
    _parsed_prompts: parsedPrompts
  }
}];

const raw = $input.first().json.data;

if (!raw) return [{ json: { error: 'No case data found' } }];

const assets = (raw.assets ?? []).map(a => ({
  name: a.asset_name,
  type: a.type,
  ip: a.asset_ip || undefined,
  domain: a.asset_domain || undefined,
  compromised: a.asset_compromise_status,
  analysis_status: a.analysis_status,
  description: a.asset_description || undefined,
}));

const iocs = (raw.iocs ?? []).map(i => ({
  type: i.type_name,
  tlp: i.tlp_name,
  description: i.ioc_description || undefined,
  tags: i.ioc_tags || undefined,
}));

const timeline = (raw.timeline ?? []).map(e => ({
  date: e.event_date,
  title: e.event_title,
  category: e.category || undefined,
  content: e.event_content || undefined,
  source: e.event_source || undefined,
  flagged: e.event_is_flagged || undefined,
  assets: e.assets,
  ioc_count: (e.iocs ?? []).length,
}));

const tasks = (raw.tasks ?? []).map(t => ({
  title: t.task_title,
  status: t.task_status,
  description: t.task_description || undefined,
  assignees: (t.task_assignees ?? []).map(a => a.name),
  open_date: t.task_open_date,
  close_date: t.task_close_date || undefined,
}));

const notes = (raw.notes ?? []).map(n => ({
  group: n.group_title,
  title: n.note_title,
  content: (n.note_content ?? '').substring(0, 1500),
}));

const evidences = (raw.evidences ?? []).map(e => ({
  filename: e.filename,
  date_added: e.date_added,
  added_by: e.added_by,
}));

const slimmed = {
  case: {
    name: raw.case?.name,
    open_date: raw.case?.open_date,
    description: raw.case?.description,
    soc_id: raw.case?.soc_id,
    opened_by: raw.case?.opened_by,
    for_customer: raw.case?.for_customer,
    status_name: raw.case?.status_name,
  },
  assets,
  iocs,
  timeline: timeline.slice(0, 50),
  tasks,
  notes: notes.slice(0, 20),
  evidences,
  export_date: raw.export_date,
  _summary_found:  $input.first().json._summary_found,
  _summary_text:   $input.first().json._summary_text,
  _prompt_count:   $input.first().json._prompt_count,
  _parsed_prompts: $input.first().json._parsed_prompts,
};

return [{ json: { data: JSON.stringify(slimmed) } }];

// Collect Summary — unchanged from original
// Also carries _parsed_prompts and _summary_text through
// for the new nodes downstream.

const agentOutput = $json.output ?? $json.text ?? JSON.stringify($json);

// Parse the slimmed data back out to recover the prompt metadata
let slimmed = {};
try {
  slimmed = JSON.parse($('Code in JavaScript').item.json.data ?? '{}');
} catch(e) {}

return [{
  json: {
    case_id:         $('Get Case List1').first().json.case_id,
    case_name:       $('Get Case List1').first().json.case_name,
    agent_analysis:  agentOutput,
    _summary_found:  slimmed._summary_found  ?? false,
    _summary_text:   slimmed._summary_text   ?? null,
    _prompt_count:   slimmed._prompt_count   ?? 0,
    _parsed_prompts: slimmed._parsed_prompts ?? []
  }
}];

// ─────────────────────────────────────────────────────────────
// SPLIT ON PROMPTS
// Takes the single item from Collect Summary and fans it out
// into one item per {{AI_PROMPT}} block extracted from the
// case summary template.
//
// Each output item contains:
//   - case_id / case_name        : for the write-back node
//   - agent_analysis             : the full AI Agent output
//                                  (used as the case context)
//   - section_index              : order in the template
//   - section_heading            : nearest markdown heading
//   - section_prompt             : verbatim prompt text
//   - prompt_placeholder         : exact block for splice-back
//   - template_summary           : full original summary string
//
// If no prompts were found the item passes through as-is
// so the workflow ends gracefully without erroring.
// ─────────────────────────────────────────────────────────────

const item    = $input.first().json;
const prompts = item._parsed_prompts ?? [];

if (!prompts.length) {
  // No prompts in this case's summary — nothing to generate
  return [{
    json: {
      ...item,
      _no_prompts: true
    }
  }];
}

return prompts.map(p => ({
  json: {
    case_id:            item.case_id,
    case_name:          item.case_name,
    template_summary:   item._summary_text,
    agent_analysis:     item.agent_analysis,  // full case context from AI Agent
    section_index:      p.index,
    section_heading:    p.heading,
    section_prompt:     p.prompt,
    prompt_placeholder: p.placeholder
  }
}));

const agentItem = $input.first().json;
const loopItem  = $('Loop Over Items').item.json;

const generatedText =
  agentItem.output ??
  agentItem.text ??
  '[Section generation failed — no content returned]';

return [{
  json: {
    case_id:            loopItem.case_id,
    case_name:          loopItem.case_name,
    template_summary:   loopItem.template_summary,
    section_index:      loopItem.section_index,
    section_heading:    loopItem.section_heading,
    prompt_placeholder: loopItem.prompt_placeholder,
    generated_text:     generatedText.trim()
  }
}];

const raw = $input.first().json;

// Unwrap Aggregate output envelope
let items;
if (Array.isArray(raw.data)) {
  items = raw.data.map(entry => entry.json ?? entry);
} else {
  items = $input.all().map(i => i.json);
}

if (!items.length) throw new Error('Assembler received no items.');

// No-prompts passthrough — nothing to assemble
if (items[0]?._no_prompts) {
  return [{
    json: {
      case_id:          items[0].case_id,
      case_name:        items[0].case_name,
      summary_markdown: null,
      _skipped:         true,
      _reason:          'No {{AI_PROMPT}} blocks found in case summary'
    }
  }];
}

// Validate template string exists
const templateSummary = items.find(i => i.template_summary)?.template_summary;
if (!templateSummary) {
  throw new Error('Assembler: no template_summary found on any item.');
}

// Sort by original order, process in reverse so earlier
// placeholder positions are not shifted by replacements
const sorted  = [...items].sort((a, b) => (a.section_index ?? 0) - (b.section_index ?? 0));
const reverse = [...sorted].reverse();

let assembled = templateSummary;

for (const section of reverse) {
  if (!section.prompt_placeholder) {
    console.warn(`Assembler: section ${section.section_index} has no placeholder. Skipping.`);
    continue;
  }
  if (!assembled.includes(section.prompt_placeholder)) {
    console.warn(`Assembler: placeholder not found for section ${section.section_index} (${section.section_heading}). Skipping.`);
    continue;
  }
  assembled = assembled.replace(section.prompt_placeholder, section.generated_text ?? '');
}

// Substitute [CASE TITLE] token with actual case name
assembled = assembled.replace(/\[CASE TITLE\]/g, items[0].case_name ?? 'Unknown Case');

// Pull case_id and case_name directly from Collect Summary
// as the reliable source — they can be dropped by the Aggregate
const case_id   = $('Collect Summary').first().json.case_id;
const case_name = $('Collect Summary').first().json.case_name;

return [{
  json: {
    case_id:          case_id,
    case_name:        case_name,
    summary_markdown: assembled
  }
}];

const result   = $input.first().json;
const prevData = $('Assemble Summary').item.json;

// Skipped — no prompts in this case's summary
if (prevData._skipped) {
  return [{
    json: {
      status:     'skipped',
      case_id:    prevData.case_id,
      case_name:  prevData.case_name,
      message:    prevData._reason
    }
  }];
}

const success = result.status === 1 || result.data !== undefined || result.success === true;

return [{
  json: {
    status:     success ? 'success' : 'warning',
    case_id:    prevData.case_id,
    case_name:  prevData.case_name,
    message:    success
      ? `Summary written to IRIS case #${prevData.case_id} — "${prevData.case_name}".`
      : `Summary generated but IRIS write response was unexpected. Verify case #${prevData.case_id} manually.`,
    iris_response: result
  }
}];
